WITH catalog_agg AS ( SELECT ca.ca_state, SUM(cr.cr_net_loss) AS catalog_net_loss, AVG(cr.cr_return_quantity) AS catalog_avg_qty, COUNT(*) AS catalog_cnt FROM catalog_returns cr JOIN customer_address ca ON cr.cr_returning_addr_sk = ca.ca_address_sk JOIN household_demographics hd ON cr.cr_returning_hdemo_sk = hd.hd_demo_sk GROUP BY ca.ca_state ), web_agg AS ( SELECT ca.ca_state, SUM(wr.wr_net_loss) AS web_net_loss, AVG(wr.wr_return_quantity) AS web_avg_qty, COUNT(*) AS web_cnt FROM web_returns wr JOIN customer_address ca ON wr.wr_returning_addr_sk = ca.ca_address_sk JOIN household_demographics hd ON wr.wr_returning_hdemo_sk = hd.hd_demo_sk GROUP BY ca.ca_state ), combined AS ( SELECT COALESCE(ca.ca_state, wa.ca_state) AS state, COALESCE(catalog_net_loss, 0) AS catalog_net_loss, COALESCE(web_net_loss, 0) AS web_net_loss, (COALESCE(catalog_net_loss, 0) + COALESCE(web_net_loss, 0)) AS total_net_loss, CASE WHEN (COALESCE(catalog_net_loss, 0) + COALESCE(web_net_loss, 0)) > 10000 THEN 'HIGH' ELSE 'LOW' END AS loss_category FROM catalog_agg ca FULL OUTER JOIN web_agg wa ON ca.ca_state = wa.ca_state ) SELECT state, total_net_loss, loss_category, RANK() OVER (ORDER BY total_net_loss DESC) AS state_rank, DENSE_RANK() OVER (ORDER BY total_net_loss DESC) AS state_dense_rank FROM combined ORDER BY state_rank
